  async function metrics11(){
    if(!['owner','manager'].includes(role())) return shell('Performance Metrics','OWNER / MANAGER','<div class="empty">Performance metrics are restricted to owner/manager accounts.</div>');
    let m; try{m=await api('/api/v11/metrics')}catch(e){return shell('Performance Metrics','OWNER / MANAGER',`<div class="install-tip">⚠️ Unable to load metrics: ${E(e.message)}</div>`)}
    const emp=m.employees||[];
    const fmt=n=>Number(n||0).toFixed(1), pct=n=>Number(n||0).toFixed(0)+'%';
    const totals=period=>emp.reduce((a,u)=>{const x=u[period]||{};for(const k of ['hours','leads','qualified','calls','contacts','appointments','sales','orders','completedOrders'])a[k]=(a[k]||0)+(Number(x[k])||0);return a},{})
    const w=totals('week'), mo=totals('month');
    const score=x=>{if(!x)return 0;if(x.leads>0)return Math.min(100,Math.round((Math.min(x.qualificationRate,100)*.45)+(Math.min(x.leadsPerHour/8*100,100)*.25)+(Math.min((x.hours/20)*100,100)*.15)+((x.rejected===0?100:Math.max(0,100-x.rejected/Math.max(1,x.leads)*100))*.15)));if(x.calls>0)return Math.min(100,Math.round((Math.min(x.closeRate/20*100,100)*.5)+(Math.min(x.appointments/10*100,100)*.25)+(Math.min(x.hours/20*100,100)*.25)));if(x.orders>0)return Math.round((x.completionRate*.7)+(Math.min(x.completedOrders/10*100,100)*.3));return 0};
    const grade=s=>s>=90?'Excellent':s>=75?'Good':s>=60?'Watch':'Needs Improvement';
    const rows=emp.map(u=>{const x=u.month||{},s=score(x);return `<tr><td><strong>${E(u.name)}</strong><div class="mini">${E(roleName[u.role]||u.role)}</div></td><td>${fmt(x.hours)}h</td><td>${x.leads||0}</td><td>${x.qualified||0}</td><td>${x.calls||0}</td><td>${x.appointments||0}</td><td>${x.sales||0}</td><td>${x.orders||0}</td><td><span class="badge ${s>=75?'green':s>=60?'orange':'red'}">${s?`${s} · ${grade(s)}`:'No data'}</span></td></tr>`}).join('')||'<tr><td colspan="9" class="empty">No team members yet.</td></tr>';
    return shell('Performance Metrics','OWNER / MANAGER · PRODUCTION SCORECARD',`<div class="install-tip">📈 <strong>Measure output, quality and business impact.</strong> Metrics are calculated from Command Center activity, time entries, CRM lead handoffs, approved call reports and fulfillment orders. This is a work-production dashboard — not keystroke or screenshot surveillance.</div><div class="grid stats section"><div class="stat"><div class="label">TEAM HOURS · 7 DAYS</div><div class="value">${fmt(w.hours)}h</div><div class="sub">Tracked work time</div></div><div class="stat"><div class="label">LEADS · 7 DAYS</div><div class="value">${w.leads||0}</div><div class="sub">Research submissions</div></div><div class="stat"><div class="label">APPOINTMENTS · 7 DAYS</div><div class="value">${w.appointments||0}</div><div class="sub">Approved sales activity</div></div><div class="stat"><div class="label">SALES · 7 DAYS</div><div class="value">${w.sales||0}</div><div class="sub">Closed/won reports</div></div></div><div class="grid three section"><div class="card"><div class="card-body"><strong>📅 This Week</strong><p class="mini">${w.leads||0} leads · ${w.calls||0} calls · ${w.appointments||0} appointments · ${w.sales||0} sales</p></div></div><div class="card"><div class="card-body"><strong>📊 This Month</strong><p class="mini">${mo.leads||0} leads · ${mo.calls||0} calls · ${mo.appointments||0} appointments · ${mo.sales||0} sales</p></div></div><div class="card"><div class="card-body"><strong>📝 60-Day Review</strong><p class="mini">Use this period for compensation/performance reviews.</p></div></div></div><div class="card section"><div class="card-head"><h2>Team Production Scorecard</h2><span class="badge blue">30 DAYS</span></div><div class="card-body"><div class="table-wrap"><table class="table"><thead><tr><th>Team Member</th><th>Hours</th><th>Leads</th><th>Qualified</th><th>Calls</th><th>Appointments</th><th>Sales</th><th>Orders</th><th>Performance</th></tr></thead><tbody>${rows}</tbody></table></div></div></div><div class="grid two section">${emp.map(u=>{const x=u.review||{},s=score(x);return card(E(u.name),`<div class="grid two"><div><div class="label">HOURS</div><div class="value">${fmt(x.hours)}h</div></div><div><div class="label">LEADS</div><div class="value">${x.leads||0}</div></div><div><div class="label">QUALIFICATION</div><div class="value">${pct(x.qualificationRate)}</div></div><div><div class="label">LEADS / HOUR</div><div class="value">${fmt(x.leadsPerHour)}</div></div><div><div class="label">APPOINTMENTS</div><div class="value">${x.appointments||0}</div></div><div><div class="label">SALES</div><div class="value">${x.sales||0}</div></div></div><div class="install-tip" style="margin-top:14px">60-day score: <strong>${s||0}</strong> — ${grade(s)}. Use with manager judgment; do not treat the score as the sole basis for pay decisions.</div>`,'60-DAY REVIEW')}).join('')}</div>`);
  }


  function production(){
    const x=d().productionScoreboard||{}, m=x.me?.metrics||{}, g=x.me?.goals||{}, p=x.phase||{}, c=x.company||null;
    const pct=(a,b)=>b?Math.min(100,Math.round(Number(a||0)/Number(b)*100)):0;
    const goal=(label,val,target)=>`<div class="stat"><div class="label">${E(label)}</div><div class="value">${E(String(val??0))}</div><div class="sub">Goal ${E(String(target??0))} · ${pct(val,target)}%</div></div>`;
    if(role()==='owner'){
      const rows=(x.team||[]).map(t=>{const z=t.metrics||{},tg=t.goals||{};return `<tr><td><strong>${E(t.user?.name||'')}</strong><div class="mini">${E(t.user?.role||'')}</div></td><td>${z.leads||0}/${tg.leads||0}</td><td>${z.verified||0}</td><td>${z.sales||0}/${tg.sales||0}</td><td>${M(z.revenue||z.reportedRevenue||0)}</td><td>${z.recurring||0}</td><td>${fmtHours(z.hours||0)}</td></tr>`}).join('')||'<tr><td colspan=7 class="empty">No workforce production data yet.</td></tr>';
      return shell('SBC Production Control','OWNER · 60-DAY COMPANY DESTINATION',`<div class="grid stats section">${goal('NEW LEADS · 7D',c?.leads||0,x.goals?.weekly?.leadResearcherLeads||100)}${goal('RECURRING CUSTOMERS · 7D',c?.recurringCustomers||0,x.goals?.weekly?.recurringCustomers||3)}${goal('NEW MRR · 7D',M(c?.newMrr||0),M(x.goals?.weekly?.newMrr||597))}${goal('SALES · 7D',c?.sales||0,x.goals?.weekly?.salesClosed||3)}</div><div class="grid two section"><div class="card"><div class="card-body"><span class="badge blue">DAY ${x.dayOf60||0} / 60</span><h2 style="margin-top:10px">${E(p.name||'PROVE')}</h2><p>${E(p.focus||'')}</p><strong>Next staffing move:</strong> ${E(p.hire||'')}</div></div><div class="card"><div class="card-body"><strong>Destination</strong><div class="value">${M(x.goals?.destination?.weeklyNewMrr||2000)} / week</div><p class="mini">This is the operating target, not a guaranteed forecast. The system records actuals.</p></div></div></div><div class="card section"><div class="card-head"><h2>Team Production</h2><span class="badge blue">LIVE</span></div><div class="card-body table-wrap"><table class="table"><thead><tr><th>Team Member</th><th>Leads</th><th>Verified</th><th>Sales</th><th>Revenue</th><th>Recurring</th><th>Hours</th></tr></thead><tbody>${rows}</tbody></table></div></div>`);
    }
    const isLorna=role()==='lead_researcher';
    const leadTarget=g.leads||100;
    return shell('My Production','WORKFORCE · YOUR GOALS & SCOREBOARD',`<div class="install-tip">🎯 <strong>Your production scoreboard.</strong> SBC measures completed work and downstream business results. It does not use keystroke or screenshot surveillance.</div><div class="grid stats section">${goal(isLorna?'LEADS · THIS WEEK':'WORK ITEMS · THIS WEEK',m.leads||0,leadTarget)}${goal('VERIFIED',m.verified||0,Math.round(leadTarget*Number(g.verifiedRate||0.9)))}${goal(isLorna?'WARM / HOT':'SALES',isLorna?(m.warmHot||0):(m.sales||0),isLorna?Math.round(leadTarget*.25):(g.sales||3))}${goal('HOURS',fmtHours(m.hours||0),20)}</div><div class="grid two section"><div class="card"><div class="card-body"><span class="badge ${pct(m.leads,leadTarget)>=100?'green':'orange'}">${pct(m.leads,leadTarget)}% GOAL</span><h2 style="margin-top:10px">${E(p.name||'PRODUCTION')}</h2><p>${E(p.focus||'Keep the pipeline moving.')}</p><div class="mini">Week starting ${E(x.weekStarting||'')}</div></div></div><div class="card"><div class="card-body"><strong>Downstream impact</strong><p class="mini">Sales: ${m.sales||0} · Recurring orders: ${m.recurring||0} · Revenue: ${M(m.revenue||m.reportedRevenue||0)}</p><p class="mini">Your work is attributed through the existing CRM, sales reports, orders and time-clock rails.</p></div></div></div>`);
  }
